import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';
import 'package:flutter/services.dart';
enum CoreStage{center,corner,hidden}
class CoreScreen extends StatefulWidget{const CoreScreen({super.key});@override State<CoreScreen> createState()=>_CoreScreenState();}
class _CoreScreenState extends State<CoreScreen> with TickerProviderStateMixin,WidgetsBindingObserver{late final Ticker ticker;Duration elapsed=Duration.zero;CoreStage stage=CoreStage.center;bool active=false;@override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);ticker=createTicker((d){elapsed=d;if(mounted)setState((){});});ticker.start();active=true;}@override void didChangeAppLifecycleState(AppLifecycleState s){if(s==AppLifecycleState.resumed){if(!active){ticker.start();active=true;}}else if(active){ticker.stop();active=false;}}@override void dispose(){WidgetsBinding.instance.removeObserver(this);ticker.dispose();super.dispose();}void nextStage()=>setState(()=>stage=CoreStage.values[(stage.index+1)%CoreStage.values.length]);@override Widget build(BuildContext context)=>Scaffold(backgroundColor:const Color(0xFF0A0002),body:SafeArea(child:Stack(children:[if(stage!=CoreStage.hidden)Align(alignment:stage==CoreStage.center?Alignment.center:const Alignment(0.82,-0.82),child:SizedBox(width:stage==CoreStage.center?280:90,height:stage==CoreStage.center?280:90,child:CustomPaint(painter:CorePainter(elapsed.inMilliseconds/1000)))),Align(alignment:Alignment.bottomCenter,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[const Expanded(child:TextField(decoration:InputDecoration(hintText:'Comando…'))),IconButton(onPressed:nextStage,icon:const Icon(Icons.crop_free,color:Color(0xFFE50914))),IconButton(onPressed:()=>HapticFeedback.lightImpact(),icon:const Icon(Icons.mic,color:Color(0xFFE50914)))]))])));}
class CorePainter extends CustomPainter{CorePainter(this.time);final double time;@override void paint(Canvas canvas,Size size){final p=Paint()..color=const Color(0xFFE50914)..style=PaintingStyle.stroke..strokeWidth=1.3;final c=size.center(Offset.zero);for(int i=0;i<3;i++){canvas.drawCircle(c,size.shortestSide*(0.22+i*0.12),p);}canvas.drawCircle(c,size.shortestSide*0.07,Paint()..color=const Color(0xFFFF1A24));}@override bool shouldRepaint(covariant CorePainter old)=>old.time!=time;}
